COPY public.protocols (id, name, description, category, estimated_time, steps, created_at, updated_at) FROM stdin;
1	DNA Extraction	Standard genomic DNA extraction protocol	Molecular Biology	120	[{"id": 1, "type": "instruction", "title": "Sample Preparation", "duration": 10, "description": "Prepare bacterial culture sample", "instructions": ["Centrifuge 1.5ml of overnight culture at 10,000 rpm for 2 minutes", "Discard supernatant", "Resuspend pellet in 200µl PBS"]}, {"id": 2, "type": "timed", "timer": 15, "title": "Cell Lysis", "duration": 15, "reminder": "Check temperature is at 65°C", "description": "Lyse bacterial cells", "instructions": ["Add 200µl lysis buffer", "Incubate at 65°C for 15 minutes"]}, {"id": 3, "type": "instruction", "title": "Protein Precipitation", "duration": 5, "description": "Remove proteins from sample", "instructions": ["Add 100µl protein precipitation solution", "Vortex vigorously for 20 seconds", "Centrifuge at 13,000 rpm for 3 minutes"]}, {"id": 4, "type": "calculation", "title": "DNA Precipitation", "duration": 20, "calculation": {"inputs": ["volume"], "output": "volume", "formula": "volume * 0.6"}, "description": "Precipitate DNA with isopropanol", "instructions": ["Transfer supernatant to new tube", "Add {volume}µl isopropanol", "Mix gently by inversion", "Incubate at room temperature for 5 minutes"]}, {"id": 5, "type": "instruction", "title": "DNA Washing", "duration": 10, "description": "Wash DNA pellet", "instructions": ["Centrifuge at 13,000 rpm for 1 minute", "Carefully remove supernatant", "Add 500µl 70% ethanol", "Centrifuge at 13,000 rpm for 1 minute", "Remove ethanol and air dry for 5 minutes"]}, {"id": 6, "type": "instruction", "title": "DNA Resuspension", "duration": 5, "description": "Resuspend DNA in TE buffer", "instructions": ["Add 50µl TE buffer", "Incubate at 65°C for 1 hour or 4°C overnight", "Store at -20°C"]}]	2026-02-16 10:02:54.534938	2026-02-16 10:02:54.534938
2	PCR Amplification	Standard PCR protocol for gene amplification	Molecular Biology	180	[{"id": 1, "type": "calculation", "title": "Reaction Setup", "duration": 15, "calculation": {"inputs": ["reactions"], "formula": "reactions * component_volume", "outputs": {"dNTPs": 1, "water": 34.5, "buffer": 5, "primer_f": 2, "primer_r": 2, "template": 5, "polymerase": 0.5}}, "description": "Prepare PCR master mix", "instructions": ["Add {water}µl nuclease-free water", "Add {buffer}µl 10X PCR buffer", "Add {dNTPs}µl dNTP mix (10mM each)", "Add {primer_f}µl forward primer (10µM)", "Add {primer_r}µl reverse primer (10µM)", "Add {polymerase}µl Taq polymerase", "Add {template}µl DNA template"]}, {"id": 2, "type": "timed", "timer": 5, "title": "Initial Denaturation", "duration": 5, "reminder": "Ensure lid is heated to 105°C", "description": "Set up thermocycler", "instructions": ["Place tubes in thermocycler", "Run: 95°C for 5 minutes"]}, {"id": 3, "type": "instruction", "title": "Cycling", "duration": 120, "description": "PCR amplification cycles", "instructions": ["30 cycles of:", "  - 95°C for 30 seconds (denaturation)", "  - 55°C for 30 seconds (annealing)", "  - 72°C for 1 minute (extension)"]}, {"id": 4, "type": "timed", "timer": 10, "title": "Final Extension", "duration": 10, "description": "Complete synthesis", "instructions": ["72°C for 10 minutes", "Hold at 4°C"]}, {"id": 5, "type": "instruction", "title": "Verification", "duration": 30, "description": "Check PCR product", "instructions": ["Run 5µl on 1% agarose gel", "Check for band at expected size", "Store remaining product at -20°C"]}]	2026-02-16 10:02:54.534938	2026-02-16 10:02:54.534938
3	Bacterial Transformation	Heat shock transformation of competent cells	Microbiology	90	[{"id": 1, "type": "timed", "timer": 10, "title": "Thaw Competent Cells", "duration": 10, "reminder": "Keep cells on ice at all times", "description": "Prepare competent cells on ice", "instructions": ["Remove competent cells from -80°C", "Thaw on ice for 10 minutes"]}, {"id": 2, "type": "calculation", "title": "Add DNA", "duration": 5, "calculation": {"inputs": ["dna_concentration", "target_ng"], "output": "dna_volume", "formula": "dna_concentration / target_ng"}, "description": "Mix plasmid with cells", "instructions": ["Add {dna_volume}µl plasmid DNA (10-100ng)", "Mix gently by flicking tube", "Incubate on ice for 30 minutes"]}, {"id": 3, "type": "timed", "timer": 2, "title": "Heat Shock", "duration": 2, "reminder": "Timing is critical - use timer!", "description": "Heat shock transformation", "instructions": ["Place tube in 42°C water bath", "Incubate for exactly 90 seconds", "Immediately transfer to ice for 2 minutes"]}, {"id": 4, "type": "timed", "timer": 60, "title": "Recovery", "duration": 60, "description": "Allow cells to recover", "instructions": ["Add 900µl SOC medium", "Incubate at 37°C with shaking (200 rpm) for 60 minutes"]}, {"id": 5, "type": "instruction", "title": "Plating", "duration": 10, "description": "Plate transformed cells", "instructions": ["Spread 100µl on LB + antibiotic plate", "Spread 10µl on second plate (dilution)", "Incubate plates inverted at 37°C overnight"]}]	2026-02-16 10:02:54.534938	2026-02-16 10:02:54.534938
